import {RAMI_COPY,EXPRESSION_IDS,ROLE_IDS,RAMI_CHAPTER_IDS} from './shared/rami-copy.js?v=5.5.0';
import {esc,icon} from './shared/core.js?v=5.5.0';
const base='assets/one-shop/rami/';
const c=lang=>RAMI_COPY[lang]||RAMI_COPY.ko;
export function ramiChapters(lang){const t=c(lang);return RAMI_CHAPTER_IDS.map((id,i)=>({id,title:t[['storyTitle','expressionsTitle','careersTitle','goodsTitle','identityTitle'][i]],rami:true}));}
const image=(path,alt,cls='',width=512,height=512)=>`<img class="${cls}" src="${base+path}" alt="${esc(alt)}" width="${width}" height="${height}" loading="lazy" decoding="async">`;
const download=(file,label,cls='text-link')=>`<a class="${cls}" href="${base+file}" download>${esc(label)}${icon('arrow')}</a>`;
const intro=(id,title,lead,note)=>`<div class="rami-section-heading"><p class="rami-eyebrow">${esc(title)}</p><h2 id="heading-${id}">${esc(lead)}</h2><p class="rami-description">${esc(note)}</p></div>`;
function selection(lang,id){const t=c(lang),label=t.expressions[EXPRESSION_IDS.indexOf(id)];return `${image('expressions/'+id+'.webp',label,'rami-selected-image')}<div><p class="rami-eyebrow">${esc(t.selectNote)}</p><h3>${esc(label)}</h3><p class="rami-selection-count">${String(EXPRESSION_IDS.indexOf(id)+1).padStart(2,'0')} / 24</p>${download('expressions/'+id+'.png',t.downloadPng)}</div>`;}
export function ramiSection(s,lang){const t=c(lang);let body='';
if(s.id==='rami')body=`${intro(s.id,t.storyTitle,t.storyLead,t.storyNote)}<div class="rami-world-scene"><div class="rami-name"><strong>라미</strong><span>rami<span class="rami-period">.</span></span><small>one shop ai</small></div>${image('hero.webp',t.world,'',1400,792)}</div><div class="rami-story-footer"><p>${esc(t.storyDetail)}</p><a class="button primary" href="#rami-expressions">${esc(t.expressionsTitle)}${icon('arrow')}</a></div>`;
if(s.id==='rami-expressions')body=`${intro(s.id,t.expressionsTitle,t.expressionsLead,t.expressionsNote)}<div class="rami-expression-preview" id="rami-expression-preview" aria-live="polite" aria-atomic="true">${selection(lang,'hello')}</div><div class="rami-sticker-sheet" role="group" aria-label="${esc(t.expressionsTitle)}">${EXPRESSION_IDS.map((id,i)=>`<button class="rami-sticker" data-expression="${id}" aria-pressed="${i===0}" aria-label="${esc(t.expressions[i])}">${image('expressions/'+id+'.webp','')}<span>${esc(t.expressions[i])}</span></button>`).join('')}</div><div class="rami-download-row">${download('rami-brand-kit.zip',t.downloadKit,'button secondary')}<span>24 PNG · 512 × 512px</span></div>`;
if(s.id==='rami-careers')body=`${intro(s.id,t.careersTitle,t.careersLead,t.careersNote)}<div class="rami-role-gallery">${ROLE_IDS.map((id,i)=>`<figure>${image('roles/'+id+'.webp',t.roles[i])}<figcaption><h3>${esc(t.roles[i])}</h3><p>${esc(t.duties[i])}</p>${download('roles/'+id+'.png',t.downloadPng)}</figcaption></figure>`).join('')}</div>`;
if(s.id==='rami-goods')body=`${intro(s.id,t.goodsTitle,t.goodsLead,t.goodsNote)}<figure class="rami-goods-photo">${image('goods.webp',t.goods.join(' · '),'',1400,792)}<figcaption>${esc(t.concept)}</figcaption></figure><ul class="rami-products">${t.goods.map(name=>`<li>${esc(name)}</li>`).join('')}</ul><div class="rami-voucher"><div><p class="rami-eyebrow">${esc(t.goodsTitle)}</p><h3>${esc(t.voucherTitle)}</h3><p>${esc(t.voucherNote)}</p>${download('bi/rami-gift-voucher-'+lang+'.svg',t.downloadSvg,'button secondary')}</div><figure>${image('vouchers.webp',t.voucherTitle,'',1400,792)}<figcaption>${esc(t.concept)}</figcaption></figure></div>`;
if(s.id==='rami-identity')body=`${intro(s.id,t.identityTitle,t.identityLead,t.identityNote)}<div class="rami-logo-showcase"><img src="${base}bi/rami-lockup.svg" alt="라미 rami · one shop ai" width="960" height="320" loading="lazy"><div><h3>${esc(t.logo)}</h3>${download('bi/rami-lockup.svg',t.downloadSvg)}</div></div><div class="rami-color-heading"><h3>${esc(t.colors)}</h3></div><div class="rami-palette">${['#AEC8EB','#172D46','#FFE395','#F5FAFF','#FFFFFF'].map((hex,i)=>`<div><i style="background:${hex}"></i><b>${esc(t.colorNames[i])}</b><code>${hex}</code></div>`).join('')}</div><div class="rami-type-specimen"><div><h3>${esc(t.type)}</h3><p>${esc(t.typeNote)}</p></div><div class="rami-type-sample"><strong>${esc(t.typeSample)}</strong><small>Pretendard · Aa 0123456789</small></div></div><div class="rami-icons-specimen"><div><h3>${esc(t.icons)}</h3><p>${esc(t.iconNote)}</p></div><div class="rami-icon-sizes">${[64,192,512].map(size=>`<a href="${base}bi/rami-icon-${size}.png" download aria-label="${esc(t.downloadPng)} · ${size}px"><img src="${base}bi/rami-icon-${size}.png" alt="Rami" width="${size===64?48:size===192?72:96}" height="${size===64?48:size===192?72:96}" loading="lazy"><span>${size}px ${icon('arrow')}</span></a>`).join('')}</div></div><div class="rami-rules"><div class="rami-clearspace"><img src="assets/one-shop/blue-mascot.webp" width="140" height="140" alt="Rami"><span>¼ D</span></div><div><h3>${esc(t.rules)}</h3><p>${esc(t.ruleNote)}</p></div></div><div class="rami-download-row">${download('rami-brand-kit.zip',t.downloadKit,'button primary')}<span>PNG · WebP · SVG · README</span></div>`;
return `<section id="${s.id}" class="book-chapter chapter rami-chapter" aria-labelledby="heading-${s.id}">${body}</section>`;
}
export function bindRami(lang){document.querySelectorAll('[data-expression]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.expression;document.querySelectorAll('[data-expression]').forEach(el=>el.setAttribute('aria-pressed',String(el===button)));document.querySelector('#rami-expression-preview').innerHTML=selection(lang,id);}));}
